SELECT COUNT(*) AS entry_count
  FROM "tbl_je_line_item"
  WHERE EXTRACT(YEAR FROM "TransactionDate") = 2021;

SELECT "Vendor", "Name", "APBalance"
  FROM "tbl_vendor"
  WHERE "APBalance" > (
    SELECT AVG("APBalance") FROM "tbl_vendor" WHERE "APBalance" IS NOT NULL AND "APBalance" > 0
  )
  ORDER BY "APBalance" DESC;

